"""Plain-text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed
from datetime import date

def _check_owner(
    student: Student, marks: List[Mark]
) -> None:
    wanted = student.student_id
    for mark in marks:
        if mark.student_id != wanted:
            raise ProjectError(
                f"mark for {mark.student_id!r} is "
                f"not for {wanted!r}"
            )

def _day_phrase(count: int) -> str:
    return "1 day" if count == 1 else f"{count} days"

def _dates_line(days: List[date]) -> str:
    return ", ".join(day.isoformat() for day in days)

def _absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    _check_owner(student, marks)
    days = days_missed(marks)
    if not days:
        raise ProjectError("no absences to write about")
    return days

# ---
def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Write a short notice of the absent days, in order."""
    days = _absent_days(student, list(marks))
    name = f"{student.first_name} {student.last_name}"
    head = f"{name} missed {_day_phrase(len(days))}."
    return f"{head}\nDates: {_dates_line(days)}\n"
